//! Host-only generator for the committed weave wallpaper assets.
//!
//! This example is the single producer of the BMPs and their manifests: it
//! calls the exact same `libwoven::design_system::wallpaper` renderer the host
//! tests validate, so generated bytes and specification cannot drift.
//!
//! Run from the repository root:
//!   cargo run -p libwoven --example generate_wallpapers

use std::fs;
use std::path::PathBuf;

use libwoven::design_system::wallpaper::{self, Variant};
use sha2::{Digest, Sha256};

const WIDTH: u16 = 320;
const HEIGHT: u16 = 200;

fn main() {
    let directory = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("libwoven has a parent directory")
        .join("assets")
        .join("wallpapers");
    fs::create_dir_all(&directory).expect("create wallpaper asset directory");

    for variant in Variant::ALL {
        let spec = variant.spec(WIDTH, HEIGHT);
        let length = wallpaper::bmp_len(WIDTH, HEIGHT).expect("bounded wallpaper geometry");
        let mut bytes = vec![0u8; length];
        wallpaper::render_bmp(&spec, &mut bytes).expect("render wallpaper");

        let stem = format!("wovenhat-weave-{}-{WIDTH}x{HEIGHT}", variant.name());
        let bmp_path = directory.join(format!("{stem}.bmp"));
        fs::write(&bmp_path, &bytes).expect("write wallpaper BMP");

        let digest = Sha256::digest(&bytes);
        let mut hex = String::with_capacity(64);
        for byte in digest.iter() {
            hex.push_str(&format!("{byte:02x}"));
        }
        let manifest = format!(
            "id = \"{stem}\"\n\
             license = \"CC0-1.0\"\n\
             source = \"WovenHat original procedural weave wallpaper ({name} variant) generated by libwoven/examples/generate_wallpapers.rs from design_system::wallpaper; derived from the WALLPAPER_TOP/WALLPAPER_BOTTOM identity and diagonal weave motif\"\n\
             dimensions = [{WIDTH}, {HEIGHT}]\n\
             format = \"BMP24\"\n\
             sha256 = \"{hex}\"\n",
            name = variant.name()
        );
        let manifest_name = format!("weave-{}-{WIDTH}x{HEIGHT}.manifest.toml", variant.name());
        fs::write(directory.join(manifest_name), manifest).expect("write wallpaper manifest");
        println!("wrote {}", bmp_path.display());
    }
}
